      "path": "server/mcp-server.cjs",
      "content": "/**\n * MRD MCP Server — Phase 1.5\n * 协议: JSON-RPC 2.0 over Streamable HTTP (SSE chunks)\n * 零新依赖，同进程复用 cached() 共享缓存\n *\n * 注入: createMcpServer({ fetchText, fetchTextAny, curlText, cache, cacheSet,\n *                           cached, entry, failEntry, quoteBackoff, TTLS,\n *                           num, changeOf, pctOf, fmtHHMM, parseCsvParam,\n *                           chunked, safeRecord, toMarketCode6,\n *                           handleQuotes, handleMinute, handleBoards,\n *                           handleBoardStocks, handleFutures, handleFutureMinute,\n *                           handleMoneyFlowEM, handleRank, handleNews,\n *                           handleStockSearch })\n */\n\"use strict\";\n\nconst { parseCsvParam } = require(\"./lib/netutil.cjs\");\n\n// ---- JSON-RPC 2.0 helpers ----\nfunction jsonrpcResult(id, result) {\n  return { jsonrpc: \"2.0\", id, result };\n}\nfunction jsonrpcError(id, code, message) {\n  return { jsonrpc: \"2.0\", id: id ?? null, error: { code, message } };\n}\nfunction parseReq(body) {\n  if (typeof body === \"string\" || Buffer.isBuffer(body)) {\n    try { return JSON.parse(String(body)); } catch { return null; }\n  }\n  return body || null;\n}\n\n// ---- MRD 内置工具清单 (public, 5 tools) ----\nconst TOOLS = [\n  {\n    name: \"get_quotes\",\n    description: \"获取 A股/港股/美股/外汇实时行情。输入股票代码列表（逗号分隔，如 sh000001,hkHSI,usNVDA），支持腾讯 6 位市场前缀。返回: 代码、名称、现价、涨跌幅、成交量、成交额。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        codes: {\n          type: \"string\",\n          description: \"股票代码，逗号分隔。示例: sh000001,sz399001,hkHSI,usNVDA\",\n        },\n      },\n      required: [\"codes\"],\n    },\n  },\n  {\n    name: \"get_boards\",\n    description: \"获取沪深/港股/美股板块涨跌排行。type=01(沪深行业) | 02(沪深概念) | 03(港股行业) | 05(美股)；dir=0(降序) | 1(升序)；n=返回条数(默认30)。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        type: {\n          type: \"string\",\n          description: \"板块类型: 01=沪深行业, 02=沪深概念, 03=港股行业, 05=美股（默认01）\",\n          default: \"01\",\n        },\n        dir: {\n          type: \"string\",\n          description: \"排序方向: 0=降序(跌幅前列), 1=升序(涨幅前列)（默认0）\",\n          default: \"0\",\n        },\n        n: {\n          type: \"string\",\n          description: \"返回条数（默认30）\",\n          default: \"30\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_futures\",\n    description: \"获取贵金属/原油/商品期货实时行情。默认列表: hf_GC(纽约金),hf_XAU(现货金),hf_SI(纽约银),hf_CAD(加元),hf_CL(原油),hf_VX(VIX恐慌),nf_AU0(国内黄金),BTCUSDT。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        list: {\n          type: \"string\",\n          description: \"期货代码列表，逗号分隔。示例: hf_GC,hf_XAU,hf_CL\",\n          default: \"hf_GC,hf_XAU,hf_SI,hf_CAD,hf_CL,hf_VX,nf_AU0,BTCUSDT\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_money_flow\",\n    description: \"获取 A股主力资金净流入排行。东财主源，失败回退新浪。n=返回条数（默认20）。返回: 代码、名称、主力净流入、主力净流入占比。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        n: {\n          type: \"string\",\n          description: \"返回条数（默认20）\",\n          default: \"20\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_news\",\n    description: \"获取新浪 7×24 快讯。page=页码（默认1），size=每页条数（默认40）。返回: 时间、标题、来源、摘要。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        page: {\n          type: \"string\",\n          description: \"页码（默认1）\",\n          default: \"1\",\n        },\n        size: {\n          type: \"string\",\n          description: \"每页条数（默认40）\",\n          default: \"40\",\n        },\n      },\n    },\n  },\n];\n\n// ---- 工具执行器 ----\nasync function callTool(name, args, ctx) {\n  const { handleQuotes, handleBoards, handleBoardStocks, handleFutures,\n          handleMoneyFlowEM, handleRank, handleNews, handleStockSearch } = ctx;\n  switch (name) {\n    case \"get_quotes\": {\n      const codes = parseCsvParam(args.codes || \"\");\n      if (!codes.length) return { error: \"codes is required\" };\n      return handleQuotes(codes.join(\",\"));\n    }\n    case \"get_boards\": {\n      const type = args.type || \"01\";\n      const dir = args.dir || \"0\";\n      const n = args.n || \"30\";\n      return handleBoards(type, dir, n);\n    }\n    case \"get_futures\": {\n      const list = args.list || \"hf_GC,hf_XAU,hf_SI,hf_CAD,hf_CL,hf_VX,nf_AU0,BTCUSDT\";\n      return handleFutures(list);\n    }\n    case \"get_money_flow\": {\n      const n = args.n || \"20\";\n      // 先试东财，失败回退新浪\n      const em = await handleMoneyFlowEM(n).catch(() => null);\n      if (em && em.length) return em;\n      return handleRank(\"changepercent\", \"0\", \"5\").catch(() => []);\n    }\n    case \"get_news\": {\n      const page = args.page || \"1\";\n      const size = args.size || \"40\";\n      return handleNews(page, size);\n    }\n    default:\n      return { error: `Unknown tool: ${name}` };\n  }\n}\n\n// ---- MCP Streamable HTTP 会话 ----\nfunction createMcpSession(ctx) {\n  const clients = new Set(); // 持有 pending SSE 响应的 write 函数\n\n  // 推送一个 JSON-RPC 消息到所有已连接的客户端\n  function broadcast(msg) {\n    const data = `data: ${JSON.stringify(msg)}\\n\\n`;\n    for (const write of clients) {\n      try { write(data); } catch { clients.delete(write); }\n    }\n  }\n\n  // 主动通知（server → client）\n  function notify(method, params) {\n    broadcast({ jsonrpc: \"2.0\", method, params });\n  }\n\n  // 请求处理器（同步，返回值给 SSE 流）\n  async function handleRequest(body) {\n    const req = parseReq(body);\n    if (!req) return jsonrpcError(null, -32700, \"Parse error\");\n\n    // 单个请求\n    if (req.method) return handleSingle(req);\n\n    // 批量请求\n    if (Array.isArray(req)) {\n      const results = await Promise.all(req.map(r => handleSingle(r)));\n      return results;\n    }\n\n    return jsonrpcError(null, -32600, \"Invalid Request\");\n  }\n\n  async function handleSingle(req) {\n    const id = req.id;\n    const method = req.method || \"\";\n    const params = req.params || {};\n\n    switch (method) {\n      case \"initialize\":\n        return jsonrpcResult(id, {\n          protocolVersion: \"2024-11-05\",\n          capabilities: { tools: {}, resources: {} },\n          serverInfo: { name: \"mrd\", version: \"1.3.2\" },\n        });\n\n      case \"tools/list\":\n        return jsonrpcResult(id, { tools: TOOLS });\n\n      case \"tools/call\": {\n        const { name, arguments: args = {} } = params;\n        if (!name) return jsonrpcError(id, -32602, \"Missing tool name\");\n        try {\n          const result = await callTool(name, args, ctx);\n          return jsonrpcResult(id, {\n            content: [\n              {\n                type: \"text\",\n                text: typeof result === \"object\" ? JSON.stringify(result, null, 2) : String(result),\n              },\n            ],\n          });\n        } catch (e) {\n          return jsonrpcError(id, -32603, e?.message || \"Tool call failed\");\n        }\n      }\n\n      case \"resources/list\":\n        return jsonrpcResult(id, {\n          resources: [\n            { uri: \"mrd://health\", name: \"健康状态\", mimeType: \"application/json\" },\n            { uri: \"mrd://stats\", name: \"服务统计\", mimeType: \"application/json\" },\n          ],\n        });\n\n      case \"resources/read\": {\n        const uri = params.uri || \"\";\n        if (uri === \"mrd://health\") {\n          return jsonrpcResult(id, {\n            contents: [{ uri, mimeType: \"application/json\", text: JSON.stringify({ status: \"ok\", ts: Date.now() }) }],\n          });\n        }\n        if (uri === \"mrd://stats\") {\n          const { cache } = ctx;\n          return jsonrpcResult(id, {\n            contents: [{\n              uri, mimeType: \"application/json\",\n              text: JSON.stringify({ cacheSize: cache.size, ts: Date.now() }),\n            }],\n          });\n        }\n        return jsonrpcError(id, -32602, `Unknown resource: ${uri}`);\n      }\n\n      case \"ping\":\n        return jsonrpcResult(id, null);\n\n      default:\n        return jsonrpcError(id, -32601, `Method not found: ${method}`);\n    }\n  }\n\n  // Streamable HTTP: 创建 SSE 响应流（客户端 long-poll）\n  function createSseStream() {\n    let closed = false;\n    const chunks = [];\n\n    function write(data) {\n      if (!closed) chunks.push(data);\n    }\n\n    function close() {\n      closed = true;\n      clients.delete(write);\n    }\n\n    clients.add(write);\n\n    return {\n      write,\n      close,\n      getChunks: () => chunks,\n    };\n  }\n\n  return { handleRequest, notify, createSseStream };\n}\n\n// ---- MCP HTTP 处理函数（挂载到 /mcp 路由）----\n// 签名兼容 index.cjs routes{} 约定: (q, body, req)\n// MCP 自身不使用 q/body，由内部 readBodyWithLimit 从 req 直接读\nfunction createMcpHandler(ctx) {\n  const { handleRequest, createSseStream } = createMcpSession(ctx);\n\n  // 读取带限的请求体\n  function readBodyWithLimit(req, limit = 256 * 1024) {\n    return new Promise((resolve) => {\n      const chunks = [];\n      let size = 0;\n      let settled = false;\n      const done = (buf) => { if (!settled) { settled = true; resolve(buf); } };\n      req.on(\"data\", (chunk) => {\n        size += chunk.length;\n        if (size > limit) { req.removeAllListeners(\"data\"); req.resume(); done(null); return; }\n        chunks.push(chunk);\n      });\n      req.on(\"end\", () => done(Buffer.concat(chunks)));\n      req.on(\"error\", () => done(null));\n      req.on(\"close\", () => done(Buffer.concat(chunks)));\n    });\n  }\n\n  return async function handleMcp(_q, body, req, res) {\n    const u = new URL(req.url, \"http://localhost\");\n\n    // 提取 lastEventId（SSE 重连用）\n    const lastEventId = req.headers[\"last-event-id\"] || u.searchParams.get(\"lastEventId\") || null;\n\n    // Streamable HTTP: 区分 SSE 端点和 POST 端点\n    if (u.pathname === \"/mcp/stream\" || u.searchParams.get(\"stream\") === \"true\") {\n      // SSE 模式: 建立持久连接，接收服务端推送\n      res.writeHead(200, {\n        \"Content-Type\": \"text/event-stream\",\n        \"Cache-Control\": \"no-cache\",\n        \"Connection\": \"keep-alive\",\n        \"X-Accel-Buffering\": \"no\", // 禁用 Nginx 缓冲\n        ...(lastEventId ? { \"Last-Event-Id\": lastEventId } : {}),\n      });\n\n      const stream = createSseStream();\n\n      // 发送初始 ping\n      stream.write(`data: ${JSON.stringify({ jsonrpc: \"2.0\", method: \"initialized\", params: {} })}\\n\\n`);\n\n      req.on(\"close\", () => stream.close());\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // POST: 处理 JSON-RPC 请求\n    if (req.method === \"POST\") {\n      // body 已由 index.cjs server 回调预解析（req.on(\"data\") 已消费 stream）\n      // index.cjs 解析成功时传入非空 body；解析失败时抛 400 由 index.cjs 处理，handler 不到达\n      if (!body || (typeof body === \"object\" && body.__rawResponse === undefined && Object.keys(body).length === 0 && req.headers[\"content-type\"]?.includes(\"application/json\"))) {\n        // body 是空对象且 content-type 是 json —— index.cjs 解析失败后抛错，handler 不应到达\n        res.writeHead(400, { \"Content-Type\": \"application/json\" });\n        res.end('{\"jsonrpc\":\"2.0\",\"error\":{\"code\":-32700,\"message\":\"Missing request body\"}}');\n        return;\n      }\n      const result = await handleRequest(body);\n      const respBody = JSON.stringify(result);\n      res.writeHead(200, {\n        \"Content-Type\": \"application/json\",\n        \"Content-Length\": Buffer.byteLength(respBody),\n        \"Cache-Control\": \"no-store\",\n      });\n      res.end(respBody);\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // GET: 返回 MCP 端点元数据\n    if (req.method === \"GET\") {\n      const meta = {\n        name: \"mrd\",\n        version: \"1.3.2\",\n        description: \"Market Research Dashboard MCP Server — A股/港股/美股/期货/资金流/快讯\",\n        endpoint: \"/mcp\",\n        streamEndpoint: \"/mcp/stream\",\n        protocol: \"JSON-RPC 2.0 over Streamable HTTP\",\n        tools: TOOLS.map((t) => ({ name: t.name, description: t.description.split(\"\\n\")[0] })),\n        resources: [\n          { uri: \"mrd://health\", name: \"健康状态\" },\n          { uri: \"mrd://stats\", name: \"服务统计\" },\n        ],\n      };\n      const body = JSON.stringify(meta, null, 2);\n      res.writeHead(200, {\n        \"Content-Type\": \"application/json\",\n        \"Content-Length\": Buffer.byteLength(body),\n        \"Cache-Control\": \"no-store\",\n      });\n      res.end(body);\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // 方法不允许\n    res.writeHead(405, { \"Content-Type\": \"application/json\", \"Allow\": \"GET, POST\" });\n    res.end('{\"ok\":false,\"error\":\"method not allowed\"}');\n    return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n  };\n}\n\nmodule.exports = { createMcpHandler, createMcpSession };\n"
    },
    {
      "path": "server/sources/eastmoney.cjs",
      "content": "// 东财 + 新浪行情源 — 榜单/资金流/板块\n\"use strict\";\n\nmodule.exports = function createEastmoney(ctx) {\n  const { fetchWithFallback, cache, cacheSet, num, toMarketCode6 } = ctx;\n  const { entry, failEntry, quoteBackoff, TTLS, qqRank } = ctx;\n\n  const EM_REFERER = \"https://quote.eastmoney.com/\"; // 东财接口统一 Referer\n\n  /* ---------------- 新浪接口(fetch/curl 双通道, 见 lib/fetch-any.cjs) ---------------- */\n  async function fetchSinaJson(url, { referer } = {}) {\n    return JSON.parse(await fetchWithFallback(url, { referer }));\n  }\n\n  /* ---------------- 个股榜单(涨幅/跌幅/热门) — 新浪盘中 + 腾讯盘后双源 ---------------- */\n  async function rankViaSina(sort, asc, want) {\n    const fetchN = Math.min(100, Math.max(want * 3, 60));\n    const url = `https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/Market_Center.getHQNodeData?page=1&num=${fetchN}&sort=${encodeURIComponent(sort)}&asc=${encodeURIComponent(asc)}&node=hs_a&symbol=&_s_r_a=page`;\n    const arr = await fetchSinaJson(url);\n    if (!Array.isArray(arr)) return [];\n    return arr.filter((s) => num(s.trade) > 0).slice(0, want).map((s) => ({\n      symbol: s.symbol,\n      code: s.code,\n      name: s.name,\n      price: num(s.trade),\n      change: num(s.pricechange),\n      pct: num(s.changepercent),\n      open: num(s.open),\n      high: num(s.high),\n      low: num(s.low),\n      vol: num(s.volume),\n      amount: num(s.amount), // 元\n      pe: num(s.per),\n      pb: num(s.pb),\n      total_mv: num(s.mktcap), // 万元\n      circ_mv: num(s.nmc), // 万元\n      turnover: num(s.turnoverratio),\n      time: s.ticktime,\n    }));\n  }\n\n  async function rankViaTencent(sort, asc, want) {\n    // 盘后新浪清零,腾讯保留收盘价;涨跌幅字段同样清零(返回0)\n    const sortMap = { changepercent: \"PriceRatio\", amount: \"volume\", turnoverratio: \"PriceRatio\" };\n    const list = await qqRank.getBoardRankList({\n      boardCode: \"aStock\",\n      sortType: sortMap[sort] || \"PriceRatio\",\n      direct: asc === \"1\" ? \"up\" : \"down\",\n      offset: 0,\n      count: want,\n    });\n    return list\n      .filter((s) => num(s.zxj) > 0)\n      .map((s) => ({\n        symbol: s.code,\n        code: s.code.slice(2),\n        name: s.name,\n        price: num(s.zxj),\n        change: num(s.zd),\n        pct: num(s.zdf),\n        open: 0, high: 0, low: 0,\n        vol: num(s.volume),\n        amount: qqRank.estAmount(s), // 成交量(手)估算成交额, 公式见 lib/qq-rank.cjs\n        pe: num(s.pe_ttm),\n        pb: 0,\n        total_mv: num(s.zsz) * 10000,\n        circ_mv: num(s.ltsz) * 10000,\n        turnover: num(s.hsl),\n        time: \"\",\n      }));\n  }\n\n  async function handleRank(sort, asc, n) {\n    const want = parseInt(n) || 30;\n    try {\n      const rows = await rankViaSina(sort, asc, want);\n      if (rows.length) return rows;\n    } catch { /* 新浪不可用则走腾讯 */ }\n    return rankViaTencent(sort, asc, want);\n  }\n\n  /* ---------------- 新浪个股主力资金流(兜底) ---------------- */\n  async function handleMoneyFlow(n) {\n    const url = `https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/MoneyFlow.ssl_bkzj_ssggzj?page=1&num=${n}&sort=netamount&asc=0`;\n    const arr = await fetchSinaJson(url);\n    if (!Array.isArray(arr)) return [];\n    return arr.filter((s) => typeof s.name === \"string\" && s.name.trim()).map((s) => ({\n      symbol: s.symbol,\n      name: s.name,\n      price: num(s.trade),\n      pct: +(num(s.changeratio) * 100).toFixed(2),\n      amount: num(s.amount),\n      netIn: num(s.netamount), // 主力净流入(元)\n      netRatio: +(num(s.ratioamount) * 100).toFixed(2),\n      r0Net: num(s.r0_net), // 超大单净流入\n      turnover: num(s.turnover),\n    }));\n  }\n\n  /* ---------------- 个股所属板块(东财): 行业/地域/概念 ---------------- */\n  /* 东财对突发请求会断连(WAF), 串行队列 + 双节点 + fetch/curl 双通道兜底 */\n  let emQueue = Promise.resolve();\n  let emPending = 0; // 排队+执行中的任务数\n  const EM_QUEUE_MAX = 20;\n  function emEnqueue(fn) {\n    // 队列满直接拒绝, 不再无界排队(err.status 供路由层返回 503)\n    if (emPending >= EM_QUEUE_MAX) {\n      const err = new Error(\"busy, retry later\");\n      err.status = 503;\n      return Promise.reject(err);\n    }\n    emPending++;\n    const run = () => fn().finally(() => { emPending--; });\n    const p = emQueue.then(run, run);\n    emQueue = p.catch(() => {});\n    return p;\n  }\n\n  async function handleStockBoards(code) {\n    const m = String(code || \"\").toLowerCase().match(/^(sh|sz|bj|nq)(\\d{6})$/);\n    if (!m) throw Object.assign(new Error(`bad code: ${code}`), { status: 400 });\n    const market = m[1] === \"sh\" ? 1 : 0;\n    return emEnqueue(async () => {\n      // 双节点 × fetch/curl 双通道 × 节流, 统一走 fetchWithFallback(见 lib/fetch-any.cjs);\n      // accept 校验 \"HTTP 成功但 data 为空\" 的情况, 视为失败继续下一通道\n      const text = await fetchWithFallback(\n        `https://push2delay.eastmoney.com/api/qt/stock/get?secid=${market}.${m[2]}&fields=f57,f58,f127,f128,f129`,\n        {\n          referer: EM_REFERER,\n          hosts: [\"push2.eastmoney.com\"],\n          throttle: { ok: 60, err: 400 }, // 队列节流\n          accept: (t) => { try { return !!JSON.parse(t)?.data; } catch { return false; } },\n        }\n      );\n      const d = JSON.parse(text)?.data;\n      return {\n        code: `${m[1]}${m[2]}`,\n        industry: d.f127 || \"\",\n        area: d.f128 || \"\",\n        concepts: String(d.f129 || \"\").split(\",\").filter(Boolean),\n      };\n    });\n  }\n\n  /* ---------------- 东财个股资金流(按股查询) + 主力净流入排名 ---------------- */\n  const emMarketOf = (m) => (m === \"sh\" ? 1 : 0);\n  const EM_FS = \"m:0+t:6,m:0+t:80,m:1+t:2,m:1+t:23,m:0+t:81+s:2048\";\n\n  async function emGet(url) {\n    // fetch/curl 双通道 + 成功/失败节流, 统一走 fetchWithFallback(见 lib/fetch-any.cjs)\n    return JSON.parse(await fetchWithFallback(url, {\n      referer: EM_REFERER,\n      throttle: { ok: 60, err: 400 }, // 队列节流\n    }));\n  }\n\n  const emSymbol = (code6) => toMarketCode6(code6);\n\n  /** 主力净流入排名(clist, f62 降序) */\n  async function handleMoneyFlowEM(n) {\n    return emEnqueue(async () => {\n      const fields = \"f12,f14,f2,f3,f62,f184,f66,f6,f8\";\n      const url = `https://push2delay.eastmoney.com/api/qt/clist/get?fid=f62&po=1&pz=${n}&pn=1&np=1&fltt=2&invt=2&fs=${encodeURIComponent(EM_FS)}&fields=${fields}`;\n      const diff = (await emGet(url))?.data?.diff || [];\n      return diff\n        .filter((s) => s.f14 && num(s.f2) > 0)\n        .map((s) => ({\n          symbol: emSymbol(s.f12),\n          name: s.f14,\n          price: num(s.f2),\n          pct: num(s.f3),\n          amount: num(s.f6), // 成交额(元)\n          netIn: num(s.f62), // 主力净流入(元)\n          netRatio: num(s.f184), // 主力净占比(%)\n          r0Net: num(s.f66), // 超大单净流入\n          turnover: num(s.f8),\n        }));\n    });\n  }\n\n  /** 板块成分股主力净流入排行(clist, fs=b:板块代码, f62 降序) — 与 handleMoneyFlowEM 同映射 */\n  async function handleBoardMoneyFlow(code, n) {\n    if (!/^BK\\d{4}$/.test(code)) return [];\n    return emEnqueue(async () => {\n      const fields = \"f12,f14,f2,f3,f62,f184,f66,f6,f8\";\n      const cnt = Math.min(Math.max(parseInt(n, 10) || 15, 1), 100); // 防呆: 非法/超限 n 收拢到 1..100\n      // 取数窗口放大到 max(cnt*3, 50): 上游按 f62 对全成分股排序, 本地再滤掉停牌股(f2=0)。\n      // 若不放大, 前 n 名中混入停牌股时返回行数 < n, 榜单也非严格\"交易股净流入前 n\"。\n      // 窗口内过滤后 slice 截断 → 语义: 交易中的股票按净流入前 n。\n      const win = Math.max(cnt * 3, 50);\n      const url = `https://push2delay.eastmoney.com/api/qt/clist/get?fid=f62&po=1&pz=${win}&pn=1&np=1&fltt=2&invt=2&fs=${encodeURIComponent(`b:${code}`)}&fields=${fields}`;\n      const diff = (await emGet(url))?.data?.diff || [];\n      return diff\n        .filter((s) => s.f14 && num(s.f2) > 0)\n        .slice(0, cnt)\n        .map((s) => ({\n          symbol: emSymbol(s.f12),\n          name: s.f14,\n          price: num(s.f2),\n          pct: num(s.f3),\n          amount: num(s.f6),\n          netIn: num(s.f62),\n          netRatio: num(s.f184),\n          r0Net: num(s.f66),\n          turnover: num(s.f8),\n        }));\n    });\n  }\n\n  /** 批量个股资金流(ulist 一次最多 50 只, 按 code 30s 缓存) */\n  async function handleStockFlows(codesParam, flowInflight) {\n    const list = String(codesParam || \"\")\n      .toLowerCase()\n      .split(\",\")\n      .map((s) => s.trim())\n      .filter((s) => /^(sh|sz|bj|nq)\\d{6}$/.test(s))\n      .slice(0, 150);\n    const now = Date.now();\n    const out = {};\n    const missing = [];\n    for (const c of list) {\n      const hit = cache.get(`sf:${c}`);\n      if (hit && hit.data !== undefined && now - hit.ts < 30000) out[c] = hit.data;\n      else missing.push(c);\n    }\n    if (missing.length) {\n      // 缺失列表级 inflight 去重(与 handleQuotes 同理, 防并发 miss 打爆东财)\n      const fkey = `sfi:${missing.join(\",\")}`;\n      const shared = flowInflight.get(fkey);\n      if (shared) {\n        Object.assign(out, await shared);\n      } else {\n        const p = (async () => {\n          const rs = {};\n          await emEnqueue(async () => {\n            for (let i = 0; i < missing.length; i += 50) {\n              const chunk = missing.slice(i, i + 50);\n              const secids = chunk.map((c) => `${emMarketOf(c.slice(0, 2))}.${c.slice(2)}`).join(\",\");\n              const url = `https://push2delay.eastmoney.com/api/qt/ulist.np/get?secids=${secids}&fields=f12,f62,f184&np=1&fltt=2&invt=2`;\n              const diff = (await emGet(url))?.data?.diff || [];\n              for (const d of diff) {\n                const c = emSymbol(d.f12);\n                const rec = { code: c, netIn: num(d.f62), netRatio: num(d.f184) };\n                cacheSet(`sf:${c}`, entry(rec, TTLS.STOCK_FLOW)); // 30s 命名 TTL, 见 lib/cache.cjs\n                rs[c] = rec;\n              }\n            }\n          });\n          return rs;\n        })();\n        flowInflight.set(fkey, p);\n        try {\n          Object.assign(out, await p);\n        } finally {\n          flowInflight.delete(fkey);\n        }\n      }\n    }\n    return list.map((c) => out[c]).filter(Boolean);\n  }\n\n  /** 板块实时资金流向图: 流入/流出各取前N/2, 拉取分钟级累计主力净流入 */\n  async function handleBoardFlow(n) {\n    const half = Math.max(3, Math.min(15, Math.floor((parseInt(n) || 20) / 2)));\n    return emEnqueue(async () => {\n      const pick = async (po) => {\n        const url = `https://push2delay.eastmoney.com/api/qt/clist/get?fid=f62&po=${po}&pz=${half}&pn=1&np=1&fltt=2&invt=2&fs=${encodeURIComponent(\"m:90+t:2\")}&fields=f12,f14,f62`;\n        return ((await emGet(url))?.data?.diff || []).map((b) => ({\n          code: b.f12,\n          name: b.f14,\n          netIn: num(b.f62),\n        }));\n      };\n      const [ups, downs] = await Promise.all([pick(1), pick(0)]);\n      const boards = [...ups, ...downs.filter((d) => !ups.some((u) => u.code === d.code))];\n      const out = [];\n      for (const b of boards) {\n        try {\n          const url = `https://push2delay.eastmoney.com/api/qt/stock/fflow/kline/get?secid=90.${b.code}&klt=1&lmt=0&fields1=f1,f2,f3,f7&fields2=f51,f52`;\n          const kl = (await emGet(url))?.data?.klines || [];\n          out.push({\n            ...b,\n            points: kl.map((s) => {\n              const f = s.split(\",\");\n              return { t: f[0].slice(11, 16), v: num(f[1]) }; // \"2026-07-17 09:31\" -> \"09:31\", 累计主力净流入(元)\n            }),\n          });\n        } catch {\n          out.push({ ...b, points: [] });\n        }\n      }\n      return out;\n    });\n  }\n\n  return { handleRank, handleMoneyFlow, handleStockBoards, handleMoneyFlowEM, handleBoardMoneyFlow, handleStockFlows, handleBoardFlow, fetchSinaJson };\n};\n"
    },
    {
      "path": "server/lib/cache.cjs",
      "content": "// 内存缓存 — 有界 LRU 风格 Map + 定时清扫 + 失败退避 + 负缓存\n// 统一实现: cached()/backoffOf(路由层) 与 tencent.cjs 第二、三套退避/负缓存(quoteBackoff/条目工厂)同源\n\"use strict\";\n\nconst CACHE_MAX = 2000;\n\n// 通用失败退避: 连续失败次数 → 退避毫秒(指数增长, 上限 5 分钟)\nconst backoffOf = (n) => Math.min(300000, 1000 * 2 ** (n || 0));\n\n// 报价通道退避(腾讯行情历史语义): 5s → 15s → 45s → 2min, 成功即复位。\n// 退避窗口内同 key 不再打上游(负缓存), 多用户场景下上游宕机时全站重复轮询折叠为每窗口 1 次\nconst FAIL_BACKOFF = [5000, 15000, 45000, 120000];\nconst quoteBackoff = (n) => FAIL_BACKOFF[Math.min(n || 0, FAIL_BACKOFF.length - 1)];\n\n// 命名 TTL(ms): 各数据源缓存键的统一刷新周期, 集中管理避免散落魔法数字\nconst TTLS = {\n  QUOTE: 5000,        // 报价: 与前端报价中心 5s 轮询对齐, 每个 code 每 5s 最多 1 次上游\n  STOCK_FLOW: 30000,  // 个股资金流(按 code)\n};\n\n// 缓存条目工厂: 统一 { ts, data, inflight, ttl, failAt, failCount } 形状\nconst entry = (data, ttl) => ({ ts: Date.now(), data, inflight: null, ttl, failAt: null, failCount: 0 });\n\n// 失败条目: 记录 failAt/failCount, 保留旧数据供退避窗口内降级返回\nconst failEntry = (prev, ttl) => ({ ts: prev?.ts || 0, data: prev?.data, inflight: null, ttl, failAt: Date.now(), failCount: (prev?.failCount || 0) + 1 });\n\nfunction createCache() {\n  const cache = new Map(); // key -> { ts, data, inflight, ttl, failAt, failCount }\n\n  function sweep() {\n    const now = Date.now();\n    for (const [k, v] of cache) {\n      if (v.inflight) continue;\n      const inBackoff = v.failAt != null && now - v.failAt < backoffOf(v.failCount);\n      if (v.data === undefined || (now - v.ts > (v.ttl || 60000) && !inBackoff)) cache.delete(k);\n    }\n  }\n\n  // 写缓存: 超限先清过期项, 仍超则按 Map 插入序淘汰最旧条目\n  function set(key, e) {\n    if (cache.has(key)) cache.delete(key); // 重插以刷新插入序\n    cache.set(key, e);\n    if (cache.size <= CACHE_MAX) return;\n    sweep();\n    while (cache.size > CACHE_MAX) {\n      let oldest;\n      for (const [k, v] of cache) {\n        if (!v.inflight) { oldest = k; break; }\n      }\n      if (oldest === undefined) break; // 全部在途, 不再淘汰\n      cache.delete(oldest);\n    }\n  }\n\n  /** 读+写合一(路由层缓存, 带新鲜度): 新鲜命中 / inflight 合并 / 退避降级或负缓存;\n      失败写回 failAt/failCount, 有旧数据降级返回(stale=true + ts=旧数据时间), 无旧数据抛错。\n      stale 只描述\"本次返回值是否来自旧数据\"(上游失败降级), 与数据源自身口径无关 */\n  async function cachedMeta(key, ttl, fn) {\n    const now = Date.now();\n    const hit = cache.get(key);\n    if (hit) {\n      if (hit.data !== undefined && now - hit.ts < (hit.ttl ?? ttl)) return { data: hit.data, ts: hit.ts, stale: false };\n      if (hit.inflight) return hit.inflight; // 在途请求: 直接复用其结果(inflight 已解析为 { data, ts, stale })\n      // 失败退避窗口内: 有旧数据降级返回, 无旧数据直接抛错 — 都不再打上游(负缓存)\n      if (hit.failAt != null && now - hit.failAt < backoffOf(hit.failCount)) {\n        if (hit.data !== undefined) return { data: hit.data, ts: hit.ts, stale: true };\n        throw new Error(\"upstream degraded\");\n      }\n    }\n    const inflight = fn()\n      .then((data) => {\n        // fn 可返回 {__ttl, ...data} 覆盖缓存 TTL(降级/快照数据用短 TTL, 过期后重试上游)\n        const effTtl = data && typeof data === \"object\" && data.__ttl ? data.__ttl : ttl;\n        const store = data && typeof data === \"object\" && data.__ttl ? { ...data } : data;\n        if (store && typeof store === \"object\" && \"__ttl\" in store) delete store.__ttl;\n        set(key, entry(store, effTtl));\n        return { data: store, ts: Date.now(), stale: false };\n      })\n      .catch((e) => {\n        const c = cache.get(key);\n        set(key, failEntry(c, ttl));\n        if (c?.data !== undefined) return { data: c.data, ts: c.ts, stale: true }; // 出错回退到旧数据\n        throw e;\n      });\n    set(key, { ts: hit?.ts || 0, data: hit?.data, inflight, ttl, failAt: hit?.failAt ?? null, failCount: hit?.failCount ?? 0 });\n    return inflight;\n  }\n\n  /** 旧签名(仅取值): 绝大多数路由不需要新鲜度, 行为与改造前逐字节一致 */\n  async function cached(key, ttl, fn) {\n    return (await cachedMeta(key, ttl, fn)).data;\n  }\n\n  const sweeper = setInterval(sweep, 60000);\n  sweeper.unref();\n\n  return { cache, set, sweep, backoffOf, cached, cachedMeta, quoteBackoff, entry, failEntry, TTLS };\n}\n\nmodule.exports = { createCache, backoffOf, quoteBackoff, entry, failEntry, TTLS, CACHE_MAX };\n"
    },
    {
      "path": "server/lib/last-good.cjs",
      "content": "// 上次成功数据快照(内存 + 磁盘) — 上游全挂时降级返回旧值并带新鲜度标记\n// 为什么需要磁盘: 内存缓存在进程重启后为空, 上游断链时冷启动会直接 502;\n// 落盘后 \"有历史成功数据就用历史\" 才在重启后依然成立。目录 server/data/ 已在 .gitignore。\n\"use strict\";\n\nmodule.exports = function createLastGood({ fs, path, dir, maxAgeMs = 7 * 24 * 3600e3, writeThrottleMs = 60e3 } = {}) {\n  const mem = new Map(); // key -> { data, at }\n  const lastWrite = new Map(); // key -> 上次落盘时间(同 key 高频写盘节流)\n\n  const fileOf = (key) => path.join(dir, `${String(key).replace(/[^\\w.-]+/g, \"_\")}.json`);\n\n  /** 读上次成功数据; 无快照/损坏/超龄(maxAgeMs)返回 null → 调用方如实报错, 不伪造 */\n  function read(key) {\n    const now = Date.now();\n    const m = mem.get(key);\n    if (m) return now - m.at < maxAgeMs ? m : null;\n    try {\n      const j = JSON.parse(fs.readFileSync(fileOf(key), \"utf-8\"));\n      if (j && j.data !== undefined && now - (j.at || 0) < maxAgeMs) {\n        mem.set(key, j);\n        return j;\n      }\n    } catch { /* 无快照或损坏: 交给调用方按\"无历史数据\"处理 */ }\n    return null;\n  }\n\n  /** 写快照: 内存立即更新(降级时立即可用), 磁盘原子写(tmp+rename)且同 key 节流 */\n  function write(key, data) {\n    if (data === undefined) return;\n    const at = Date.now();\n    mem.set(key, { data, at });\n    if (at - (lastWrite.get(key) || 0) < writeThrottleMs) return;\n    lastWrite.set(key, at);\n    try {\n      fs.mkdirSync(dir, { recursive: true });\n      const file = fileOf(key);\n      const tmp = `${file}.tmp`;\n      fs.writeFileSync(tmp, JSON.stringify({ data, at }));\n      fs.renameSync(tmp, file);\n    } catch (e) {\n      console.error(\"[last-good] write error:\", e?.message || e);\n    }\n  }\n\n  return { read, write };\n};\n"
    },
    {
      "path": "src/lib/market.ts",
      "content": "import { useEffect, useMemo, useSyncExternalStore } from \"react\";\nimport { api } from \"@/lib/api\";\nimport { isTv } from \"@/lib/tv\";\nimport { num } from \"./format\";\n\n/**\n * 统一报价中心(MarketHub)\n *  所有面板显示用的价格/涨跌幅的唯一来源:\n *  面板通过 useQuote/useQuotes 订阅需要的代码, 中心以单一轮询循环(5s)\n *  批量拉取全集并分发同一快照 — 同一只股票在所有面板永远同帧。\n *  领域数据(成分股/榜单/资金流)仍走各自端点, 仅展示价格统一从这里读。\n */\n\ninterface HubQuote {\n  /** 证券名称(供 代码→名称 解析) */\n  name?: string;\n  price: number;\n  pct: number;\n  /** 万元(仅股票有) */\n  amount?: number;\n  /** 换手率 %(仅股票有) */\n  turnover?: number;\n  updated: number;\n}\n\n// TV 模式降频: 电视弱 CPU 上全站同帧重渲染开销大, 轮询减半\n// 导出供面板(如 IndexPanel 分时)同步轮询周期, 保证报价与分时同帧刷新\nexport const POLL_MS = isTv ? 10000 : 5000;\n\nconst entries = new Map<string, HubQuote>();\nconst refCounts = new Map<string, number>();\nconst listeners = new Set<() => void>();\nlet version = 0;\nlet timer: number | null = null;\nlet flushTimer: number | null = null;\n\nconst isFuturesCode = (c: string) => /^(nf_|hf_)|BTCUSDT/.test(c);\n\nfunction emit() {\n  version++;\n  listeners.forEach((l) => l());\n}\n\nfunction subscribe(l: () => void) {\n  listeners.add(l);\n  return () => listeners.delete(l);\n}\n\nfunction getVersion() {\n  return version;\n}\n\nasync function tick() {\n  if (!refCounts.size) return;\n  const codes = [...refCounts.keys()];\n  const stocks = codes.filter((c) => !isFuturesCode(c));\n  const futures = codes.filter(isFuturesCode);\n  const jobs: Promise<Record<string, { name?: string; price: number; pct: number; amount?: number; turnover?: number }>>[] = [];\n  if (stocks.length) jobs.push(api.quotes(stocks));\n  if (futures.length) jobs.push(api.futuresBatch(futures));\n  const rs = await Promise.allSettled(jobs);\n  const now = Date.now();\n  let changed = false;\n  for (const r of rs) {\n    if (r.status !== \"fulfilled\") continue;\n    for (const [code, q] of Object.entries(r.value)) {\n      const next: HubQuote = {\n        name: typeof q.name === \"string\" ? q.name : undefined,\n        price: num(q.price),\n        pct: num(q.pct),\n        amount: q.amount != null ? num(q.amount) : undefined,\n        turnover: q.turnover != null ? num(q.turnover) : undefined,\n        updated: now,\n      };\n      const old = entries.get(code);\n      if (!old || old.price !== next.price || old.pct !== next.pct || old.amount !== next.amount || old.turnover !== next.turnover) {\n        entries.set(code, next);\n        changed = true;\n      }\n    }\n  }\n  if (changed) emit();\n  // TV 调试角标读取: 上次报价心跳时间与是否有变化(定位\"面板不更新\"是轮询死了还是行情静止)\n  (window as unknown as { __hubStatus?: { t: number; changed: boolean } }).__hubStatus = { t: Date.now(), changed };\n}\n\nfunction onVisibility() {\n  if (!document.hidden) tick();\n}\n\nfunction ensureLoop() {\n  if (timer != null) return;\n  timer = window.setInterval(() => {\n    if (!document.hidden) tick();\n  }, POLL_MS);\n  document.addEventListener(\"visibilitychange\", onVisibility);\n}\n\nfunction maybeStopLoop() {\n  if (refCounts.size === 0 && timer != null) {\n    clearInterval(timer);\n    timer = null;\n    document.removeEventListener(\"visibilitychange\", onVisibility);\n  }\n}\n\n/** 新代码注册后防抖立即补拉(节流 ≥2s, 防滚动订阅风暴直冲上游) */\nlet lastFlush = 0;\nfunction scheduleFlush() {\n  if (flushTimer != null || document.hidden) return;\n  const wait = Math.max(250, 2000 - (Date.now() - lastFlush));\n  flushTimer = window.setTimeout(() => {\n    flushTimer = null;\n    lastFlush = Date.now();\n    tick();\n  }, wait);\n}\n\n/** 注册一批代码(引用计数), 卸载时释放 */\nfunction useCodes(codes: string[]) {\n  const key = codes.join(\",\");\n  useEffect(() => {\n    const uniq = [...new Set(key ? key.split(\",\") : [])].filter(Boolean);\n    for (const c of uniq) refCounts.set(c, (refCounts.get(c) || 0) + 1);\n    ensureLoop();\n    scheduleFlush();\n    return () => {\n      for (const c of uniq) {\n        const n = (refCounts.get(c) || 1) - 1;\n        if (n <= 0) {\n          refCounts.delete(c);\n          entries.delete(c);\n        } else {\n          refCounts.set(c, n);\n        }\n      }\n      maybeStopLoop();\n    };\n  }, [key]);\n}\n\n/** 订阅单个代码的实时报价(同一快照源; entry 引用仅在该代码数据变化时更新) */\nexport function useQuote(code: string, enabled = true): HubQuote | null {\n  useCodes(enabled ? [code] : []);\n  return useSyncExternalStore(subscribe, () => (enabled ? entries.get(code) ?? null : null));\n}\n\n/** 订阅一批代码的实时报价表(同一快照源) */\nexport function useQuotes(codes: string[]): Record<string, HubQuote> {\n  useCodes(codes);\n  const v = useSyncExternalStore(subscribe, getVersion);\n  const key = codes.join(\",\");\n  return useMemo(() => {\n    const result: Record<string, HubQuote> = {};\n    for (const c of codes) {\n      const e = entries.get(c);\n      if (e) result[c] = e;\n    }\n    return result;\n    // codes 内容变化(key)或中心数据更新(v)时重建\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [key, v]);\n}\n"
    }
